package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import thaumcraft.api.aspects.*;
public final class PlacementMirror extends Item {
 static final net.neoforged.neoforge.registries.DeferredItem<PlacementMirror> ITEM=KamiRegistries.ITEMS.register("placement_mirror",PlacementMirror::new);
 public PlacementMirror(){super(new Properties().stacksTo(1).rarity(Rarity.EPIC));}
 static void init(){}
 public static int size(ItemStack s){int n=BlockTalisman.data(s).getInt("size");return n>=3&&n<=11?n|1:3;}
 static void bind(ItemStack s,net.minecraft.world.level.block.state.BlockState state){CustomData.update(DataComponents.CUSTOM_DATA,s,t->{t.putString("blockName",net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString());t.put("blockState",net.minecraft.nbt.NbtUtils.writeBlockState(state));});}
 public static java.util.List<net.minecraft.core.BlockPos> targets(ItemStack s,net.minecraft.world.entity.player.Player p){var start=p.getEyePosition();var hit=p.level().clip(new net.minecraft.world.level.ClipContext(start,start.add(p.getViewVector(1).scale(5)),net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.ANY,p));if(hit.getType()!=net.minecraft.world.phys.HitResult.Type.BLOCK)return java.util.List.of();var pos=hit.getBlockPos();if(p.level().getBlockState(pos).canBeReplaced())pos=pos.below();return PlacementMirrorPattern.positions(pos,hit.getDirection(),size(s),p.getYRot(),p.getXRot()).stream().filter(at->p.level().getBlockState(at).canBeReplaced()).toList();}
 static long available(ItemStack mirror,net.minecraft.world.entity.player.Player p){var block=BlockTalisman.block(mirror);long total=0;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(stack.is(block.asItem()))total+=stack.getCount();else if(stack.is(BlockTalisman.ITEM.get())&&BlockTalisman.block(stack)==block)total+=BlockTalisman.count(stack);}return total;}
 static void consume(ItemStack mirror,net.minecraft.world.entity.player.Player p){var item=BlockTalisman.block(mirror).asItem();for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(stack.is(item)){stack.shrink(1);p.getInventory().setChanged();return;}}for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(stack.is(BlockTalisman.ITEM.get())&&BlockTalisman.block(stack).asItem()==item&&BlockTalisman.count(stack)>0){BlockTalisman.remove(stack,1);p.getInventory().setChanged();return;}}}
 static int place(ItemStack mirror,net.minecraft.world.entity.player.Player p,java.util.List<net.minecraft.core.BlockPos> positions){var level=p.level();var block=BlockTalisman.block(mirror);if(level.isClientSide||block.asItem()==Items.AIR||!p.getAbilities().instabuild&&available(mirror,p)<positions.size())return 0;var state=net.minecraft.nbt.NbtUtils.readBlockState(level.holderLookup(net.minecraft.core.registries.Registries.BLOCK),BlockTalisman.data(mirror).getCompound("blockState"));int placed=0;for(var at:positions){if(!level.getBlockState(at).canBeReplaced()||!level.mayInteract(p,at)||!p.mayUseItemAt(at,net.minecraft.core.Direction.UP,mirror))continue;var snapshot=net.neoforged.neoforge.common.util.BlockSnapshot.create(level.dimension(),level,at);boolean outerCapture=level.captureBlockSnapshots;int previousSnapshots=level.capturedBlockSnapshots.size();boolean changed;level.captureBlockSnapshots=true;try{changed=level.setBlock(at,state,3);}finally{while(level.capturedBlockSnapshots.size()>previousSnapshots)level.capturedBlockSnapshots.removeLast();level.captureBlockSnapshots=outerCapture;}if(!changed)continue;if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snapshot,net.minecraft.core.Direction.UP)){level.restoringBlockSnapshots=true;try{snapshot.restore(3);}finally{level.restoringBlockSnapshots=false;}continue;}state.onPlace(level,at,snapshot.getState(),false);level.markAndNotifyBlock(at,level.getChunkAt(at),snapshot.getState(),state,3,512);if(!p.getAbilities().instabuild)consume(mirror,p);placed++;}return placed;}
 @Override public net.minecraft.world.InteractionResult useOn(net.minecraft.world.item.context.UseOnContext c){var p=c.getPlayer();if(p==null)return net.minecraft.world.InteractionResult.PASS;if(p.isShiftKeyDown()){var state=c.getLevel().getBlockState(c.getClickedPos());if(state.isCollisionShapeFullBlock(c.getLevel(),c.getClickedPos())&&state.getRenderShape()==net.minecraft.world.level.block.RenderShape.MODEL)bind(c.getItemInHand(),state);}else {var positions=targets(c.getItemInHand(),p);boolean enough=p.getAbilities().instabuild||available(c.getItemInHand(),p)>=positions.size();place(c.getItemInHand(),p,positions);if(enough&&!c.getLevel().isClientSide)c.getLevel().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvent.createVariableRangeEvent(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("tc4modern","wand")),net.minecraft.sounds.SoundSource.PLAYERS,1,1);}return net.minecraft.world.InteractionResult.sidedSuccess(c.getLevel().isClientSide);}
 @Override public net.minecraft.world.InteractionResultHolder<ItemStack> use(net.minecraft.world.level.Level level,net.minecraft.world.entity.player.Player p,net.minecraft.world.InteractionHand hand){var s=p.getItemInHand(hand);if(p.isShiftKeyDown()){int n=size(s);CustomData.update(DataComponents.CUSTOM_DATA,s,t->t.putInt("size",n==11?3:n+2));if(level.isClientSide)AdvancedToolHud.show(size(s)+" x "+size(s));p.playSound(net.minecraft.sounds.SoundEvents.EXPERIENCE_ORB_PICKUP,.3f,.1f);}return net.minecraft.world.InteractionResultHolder.sidedSuccess(s,level.isClientSide);}
 @Override public void appendHoverText(ItemStack s,TooltipContext c,java.util.List<net.minecraft.network.chat.Component> lines,TooltipFlag f){lines.add(net.minecraft.network.chat.Component.literal(size(s)+" x "+size(s)));if(BlockTalisman.block(s)!=net.minecraft.world.level.block.Blocks.AIR)lines.add(net.minecraft.network.chat.Component.translatable(BlockTalisman.block(s).getDescriptionId()));}
 static void research(){var r=new KamiResearch("PLACEMENT_MIRROR",new AspectList().add(Aspect.CRAFT,2).add(Aspect.CRYSTAL,1).add(Aspect.ELDRITCH,1).add(Aspect.MIND,1),17,16,5,new ItemStack(ITEM.get()));r.setParents("BLOCK_TALISMAN");r.setPages(new thaumcraft.api.research.ResearchPage("ttresearch.page.PLACEMENT_MIRROR.0"),MagnetResearch.page("PLACEMENT_MIRROR",thaumcraft.api.research.ResearchPage.PageType.INFUSION_CRAFTING)).registerResearchItem();ThaumicTinkererModern.INFUSION_RECIPES.add(new dev.eugheist.tc4modern.InfusionItemRecipes.Recipe("PLACEMENT_MIRROR","PLACEMENT_MIRROR",ITEM::get,12,new AspectList().add(Aspect.CRAFT,65).add(Aspect.CRYSTAL,32).add(Aspect.MAGIC,50).add(Aspect.MIND,32),()->BlockTalisman.ITEM.get(),java.util.List.of(()->KamiResources.item(KamiResources.Kind.ICHOR),()->Items.DROPPER,()->Items.DIAMOND,()->Items.GLASS,()->Items.BLAZE_POWDER,()->KamiResources.item(KamiResources.Kind.ICHOR))));}
}
